package com.example.kitsune.data.entity

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * Representation of a user-created named Bookmark Collection.
 *
 * @param id Unique internal identifier generated by Room.
 * @param name User-chosen name for the collection (e.g. "Favorit", "Must Read").
 * @param createdAt Timestamp when collection was created (epoch millis).
 * @param updatedAt Timestamp when collection was last modified (epoch millis).
 */
@Entity(tableName = "bookmarks")
data class BookmarkEntity(
    @PrimaryKey(autoGenerate = true)
    val id: Long = 0,
    val name: String,
    val createdAt: Long = System.currentTimeMillis(),
    val updatedAt: Long = System.currentTimeMillis()
)
